package com.myeshopping.audit;
import org.springframework.boot.*; import org.springframework.boot.autoconfigure.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*; import java.util.concurrent.*;
@SpringBootApplication @RestController @RequestMapping("/api/v1/audit") public class AuditApplication { private final List<Map<String,Object>> records=new CopyOnWriteArrayList<>(); public static void main(String[]a){SpringApplication.run(AuditApplication.class,a);} @PostMapping public Map<String,Object> record(@RequestBody Map<String,Object> event){Map<String,Object> r=new LinkedHashMap<>(event);r.put("auditId",UUID.randomUUID());r.putIfAbsent("timestamp",Instant.now());records.add(r);return r;} @GetMapping public List<Map<String,Object>> all(){return records;} }
